import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"22、【贲】 离下艮上","description":"周易口诀义 - 22、【贲】 离下艮上","frontmatter":{"title":"22、【贲】 离下艮上","description":"周易口诀义 - 22、【贲】 离下艮上"},"headers":[],"relativePath":"zh/classics/koujueyi/024.md","filePath":"zh/classics/koujueyi/024.md"}'),r={name:"zh/classics/koujueyi/024.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_22、【贲】-离下艮上" tabindex="-1">22、【贲】 离下艮上 <a class="header-anchor" href="#_22、【贲】-离下艮上" aria-label="Permalink to “22、【贲】 离下艮上”">​</a></h1><p>彖曰：「贲亨」，柔来而文刚，故「亨」。分刚上而文柔，故「小利有攸往」，天文也；文明以止，人文也。观乎天文，以察时变；观乎人文，以化成天下。</p><p>象曰：山下有火，贲。君子以明庶政，无敢折狱。</p><p>初九：贲其趾，舍车而徒。</p><p>象曰：「舍车而徒」，义弗乘也。</p><p>六二：贲其须。</p><p>象曰：「贲其须」，与上兴也。</p><p>九三：贲如濡如，永贞吉。</p><p>象曰：「永贞」之「吉」，终莫之陵也。</p><p>六四：贲如皤如，白马翰如，匪寇婚媾。</p><p>象曰：六四当位，疑也。「匪寇婚媾」，终无尤也。</p><p>六五：贲于丘园，束帛戋戋，吝，终吉。</p><p>象曰：六五之「吉」，有喜也。</p><p>上九：白贲，无咎。</p><p>象曰：「白贲无咎」，上得志也。</p><p>解读</p><p>「贲亨，小利有攸往」者，贲，饰也，以刚柔交杂而相文饰也。象曰：山下有火，贲。王廙云：「山下有火，文明相照。」夫山之为体，层峰峻岭，岩峦峭丽，参差被日光照耀，如以雕饰而见文章，贲之象也。君子以明庶政，无敢折狱。庶，众也；敢，果也；折，断也。君子以明鉴之德，必须审察，为众庶之政，无直果敢，折断狱讼，当审慎用刑也。</p><p>「初九，贲其趾，舍车而徒」者，趾，足也；处无位之地，不尚华侈，所饰在于足趾，故曰「贲其趾」；以其执志耿介，不乘不义之车，而从有义徒步，故曰「舍车而徒」也。</p><p>「六二，贲其须」，须，须也。与三相近，情意相得，以下亲上，犹如须之附面，修其所理，随之兴动，故小象云「与上兴也」。</p><p>「九三，贲如濡如，永贞吉」者，与二相得，以饰以润，故曰「贲如濡如」也；以其非应相亲，永保其正，物莫能犯，故曰「永贞吉」也。</p><p>「六四，贲如皤如，白马翰如，匪寇婚媾」者，四应在初，被三隔碍，志唯犹豫，或文或素，故曰「贲如皤如」，质素也；既不得前进，但鲜洁其马翰如，徘徊以待之矣，故曰「白马翰如」也。若非九三与己为寇难，即与初已为媾婚，故曰「匪寇婚媾」也。</p><p>「六五，贲于丘园，束帛戋戋。吝终吉」者，处得尊位，为饰之主，不尚华饰，所贲质素，故其致饰如似丘园。丘园所生草木，质素而已，则不縻费国之盈盛，乃束帛珍宝戋戋众多，故曰「贲于丘园，束帛戋戋」。若能俭而约侈，费用得宜，处约之吝，乃得终吉，故曰「吝终吉」也。</p><p>上九：白贲，无咎者，处饰之终，终乃反素矣。他人以色为饰，而我以素为饰，守志任真，得其夲性，何咎之有哉！</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
